class CsvError(Exception):
    """A CSV syntax error at a 1-based physical line and column."""

    def __init__(self, message: str, line: int, col: int):
        self.line = line
        self.col = col
        super().__init__(f"{message} (line {line}, col {col})")


def parse(text: str, dialect: dict) -> list:
    """Parse CSV using the specified dialect, assumed to be valid."""
    delimiter = dialect.get("delimiter", ",")
    quote = dialect.get("quote", '"')
    escape = dialect.get("escape", None)
    skip_initial_space = dialect.get("skip_initial_space", False)
    comment = dialect.get("comment", None)
    skip_blank = dialect.get("skip_blank", True)
    strict = dialect.get("strict", True)
    header = dialect.get("header", False)
    fill = dialect.get("fill", None)
    null_values = dialect.get("null_values", [])
    infer_ints = dialect.get("infer_ints", False)
    trim = dialect.get("trim", False)

    if text.startswith("\ufeff"):
        text = text[1:]

    n = len(text)
    pos = 0
    line = 1
    col = 1

    def take():
        """Consume one character, tracking physical source positions."""
        nonlocal pos, line, col
        ch = text[pos]
        pos += 1

        if ch == "\r":
            line += 1
            col = 1
        elif ch == "\n":
            # A preceding CR already counted this CRLF as a line break.
            if pos < 2 or text[pos - 2] != "\r":
                line += 1
            col = 1
        else:
            col += 1

        return ch

    def take_line_break():
        """Consume one complete line break at the current position."""
        ch = take()
        if ch == "\r" and pos < n and text[pos] == "\n":
            take()

    def convert(value):
        """Apply rule 10 to an unquoted, non-header field."""
        if trim:
            value = value.strip(" \t")

        if value in null_values:
            return None

        if infer_ints:
            negative = value.startswith("-")
            digits = value[1:] if negative else value

            if digits and all("0" <= ch <= "9" for ch in digits):
                # Small chunks avoid Python's configurable limit on
                # decimal-string-to-int conversion for very long fields.
                number = 0
                for start in range(0, len(digits), 9):
                    chunk = digits[start:start + 9]
                    number = number * (10 ** len(chunk)) + int(chunk)
                return -number if negative else number

        return value

    result = []
    header_names = None

    while pos < n:
        # These checks happen only at the start of a record.
        if comment is not None and text[pos] == comment:
            while pos < n and text[pos] not in "\r\n":
                take()
            if pos < n:
                take_line_break()
            continue

        if skip_blank and text[pos] in "\r\n":
            take_line_break()
            continue

        reading_header = header and header_names is None
        record = []

        # Always parse at least one field. After a delimiter, parse another
        # even if the delimiter was the final character in the text.
        while True:
            if skip_initial_space:
                while pos < n and text[pos] == " ":
                    take()

            quoted = quote is not None and pos < n and text[pos] == quote
            parts = []

            if quoted:
                opening_line, opening_col = line, col
                take()  # Opening quote.

                while True:
                    if pos == n:
                        raise CsvError(
                            "Unterminated quoted field",
                            opening_line,
                            opening_col,
                        )

                    ch = text[pos]

                    if escape is not None and ch == escape:
                        take()
                        if pos == n:
                            raise CsvError(
                                "Unterminated quoted field",
                                opening_line,
                                opening_col,
                            )
                        parts.append(take())

                    elif ch == quote:
                        take()
                        if escape is None and pos < n and text[pos] == quote:
                            parts.append(take())  # Doubled quote.
                        else:
                            break  # Closing quote.

                    else:
                        # Consume verbatim, including CR and LF separately.
                        parts.append(take())

                if (
                    pos < n
                    and text[pos] != delimiter
                    and text[pos] not in "\r\n"
                ):
                    if strict:
                        raise CsvError(
                            "Unexpected character after closing quote",
                            line,
                            col,
                        )

                    while (
                        pos < n
                        and text[pos] != delimiter
                        and text[pos] not in "\r\n"
                    ):
                        parts.append(take())

            else:
                while (
                    pos < n
                    and text[pos] != delimiter
                    and text[pos] not in "\r\n"
                ):
                    parts.append(take())

            value = "".join(parts)
            if not quoted and not reading_header:
                value = convert(value)
            record.append(value)

            if pos == n:
                break

            if text[pos] == delimiter:
                take()
                continue

            take_line_break()
            break

        if reading_header:
            header_names = []
            occurrences = {}

            for index, value in enumerate(record, start=1):
                name = value if value != "" else f"col{index}"
                count = occurrences.get(name, 0) + 1
                occurrences[name] = count
                header_names.append(name if count == 1 else f"{name}_{count}")

        elif header:
            row = {
                name: record[index] if index < len(record) else fill
                for index, name in enumerate(header_names)
            }
            if len(record) > len(header_names):
                row["_extra"] = record[len(header_names):]
            result.append(row)

        else:
            result.append(record)

    return result
